const pages=['education','home','corporate','candidate','employer','sectors','training','media','contact','privacy'];
const main=document.querySelector('#main');
const nav=document.querySelector('#navigation');
let lang='tr',page='home',draftUrl;
const t=key=>content[lang][key];
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sectorRoutes={0:'hospitality',1:'healthcare',2:'care',4:'education',5:'manufacturing',6:'energy'};
function sectorLink(index,html,cls){return `<a class="${cls}" href="${sectorRoutes[index]?'/sectors/'+sectorRoutes[index]+'?lang='+lang:pageHref('employer')}">${html}</a>`}
const pageHref=name=>name==='employment'?`/sectors?lang=${lang}`:name==='education'?`/education?lang=${lang}`:name==='privacy'?`/privacy?lang=${lang}`:name==='investment'?`/investment?lang=${lang}`:['candidate','employer','student','university'].includes(name)?`https://global-istihdam.mtoman.chatgpt.site/portal?type=${({candidate:'employee',employer:'company',student:'student',university:'university'})[name]}&lang=${lang}`:`#${lang}/${name}`;
const route=(name,label,cls='')=>`<a class="${cls}" href="${pageHref(name)}" data-page="${name}">${label}</a>`;
function readRoute(){const parts=location.hash.slice(1).split('/');let stored='tr';try{stored=localStorage.getItem('global-language')||'tr'}catch{}lang=['tr','en'].includes(parts[0])?parts[0]:stored;page=pages.includes(parts[1])?parts[1]:'home';}
function pageHeader(title,intro){return `<section class="page-hero"><div class="container"><div class="breadcrumb">${route('home',t('home'))}<span>/</span>${title}</div><h1>${title}</h1><p>${intro}</p></div></section>`}
function sectorCards(indices){return `<div class="sector-grid">${indices.map(i=>sectorLink(i,`<span class="sector-number">${String(i+1).padStart(2,'0')}</span><h3>${t('sectorNames')[i]}</h3>`,'sector-card')).join('')}</div>`}
function band(){return `<section class="band"><div class="container band-inner"><div><h2>${t('bandTitle')}</h2><p>${t('bandText')}</p></div>${route('contact',t('contactCta'),'button gold')}</div></section>`}
function workForm(employer=false){return `<form class="work-start-form" data-preference-form="${employer?'company':'employee'}" action="https://global-istihdam.mtoman.chatgpt.site/portal" method="get"><input type="hidden" name="type" value="${employer?'company':'employee'}"><input type="hidden" name="lang" value="${lang}"><label>${t(employer?'workRoleEmployer':'workRole')}<input name="position" maxlength="180" placeholder="${t(employer?'workRoleEmployerHint':'workRoleHint')}" required></label><label>${t('workLocation')}<input name="location" maxlength="180" placeholder="${t('workLocationHint')}"></label><button type="submit" class="button">${t(employer?'workEmployerCta':'workCandidateCta')}</button></form>`}
function homePage(){const tr=lang==='tr';const serviceCards=[{n:'01',tag:tr?'İSTİHDAM':'EMPLOYMENT',title:tr?'Doğru insanlarla<br>güçlü bir gelecek.':'The right people.<br>A stronger future.',text:tr?'İşverenler için sektör odaklı personel desteği. Adaylar için deneyim ve hedeflere uygun kariyer danışmanlığı.':'Sector-focused workforce support for employers. Career guidance shaped around candidates’ experience and ambitions.',image:'/energy-team.jpg',alt:tr?'Enerji sahasında çalışan mühendisler':'Engineers working at an energy site',href:'/sectors?lang='+lang,cta:tr?'İstihdam hizmetleri':'Explore recruitment',portal:pageHref('employer'),portalText:tr?'İşveren başvurusu':'Employer enquiry'},{n:'02',tag:tr?'ULUSLARARASI EĞİTİM':'INTERNATIONAL EDUCATION',title:tr?'Eğitiminiz için<br>yeni bir ufuk.':'Your education.<br>A wider horizon.',text:tr?'Ülke, üniversite ve program seçeneklerini karşılaştırın. Eğitim planınızı kişisel hedeflerinize göre oluşturun.':'Compare countries, universities and programmes. Shape your study plan around your personal goals.',image:'/students-campus.jpg',alt:tr?'Birlikte çalışan üniversite öğrencileri':'University students studying together',href:'/education?lang='+lang,cta:tr?'Üniversiteleri keşfedin':'Explore universities',portal:pageHref('student'),portalText:tr?'Öğrenci başvurusu':'Student enquiry'},{n:'03',tag:tr?'YATIRIM VE DANIŞMANLIK':'INVESTMENT & ADVISORY',title:tr?'İş hedefleriniz için<br>net bir yol.':'Your business ambitions.<br>A clear direction.',text:tr?'Türkiye, Körfez, Avrupa ve Kuzey Amerika’da pazar araştırması, kuruluş planlaması ve proje koordinasyonu.':'Market research, establishment planning and project coordination across Türkiye, the Gulf, Europe and North America.',image:'/sector-hospitality.jpg',alt:tr?'Profesyonel otel resepsiyon alanı':'Professional hotel reception area',href:'/investment?lang='+lang,cta:tr?'Yatırım rehberleri':'Explore investment guides',portal:'https://global-istihdam.mtoman.chatgpt.site/portal?type=investment&lang='+lang,portalText:tr?'Danışmanlık başvurusu':'Advisory enquiry'}];const slides=[{kicker:tr?'İNSANLAR. FIRSATLAR. YENİ BAŞLANGIÇLAR.':'PEOPLE. OPPORTUNITIES. NEW BEGINNINGS.',title:tr?'Geleceğinizi<br><span>sınırların ötesine</span><br>taşıyın.':'Take your future<br><span>beyond borders.</span>',text:tr?'İstihdam, uluslararası eğitim ve iş danışmanlığında hedefinize uygun bir sonraki adımı birlikte planlayalım.':'Find your next step in recruitment, international education and business advisory, with guidance around your goals.',image:'/energy-team.jpg',alt:serviceCards[0].alt,href:'#services',cta:tr?'Hizmetlerimizi keşfedin':'Explore our services',secondary:pageHref('contact'),secondaryText:tr?'Size nasıl yardımcı olabiliriz?':'How can we help?'},{kicker:tr?'EĞİTİMİNİZİ DÜNYAYLA BULUŞTURUN':'CONNECT YOUR EDUCATION WITH THE WORLD',title:tr?'Bir üniversiteden<br><span>çok daha fazlası.</span>':'More than a university.<br><span>Your next chapter.</span>',text:tr?'Üniversite tanıtımları, ülke rehberleri ve Final Üniversitesi’nin İngiltere’ye uzanan eğitim yolları.':'University profiles, destination guides and Final University’s study pathways to England.',image:'/students-campus.jpg',alt:serviceCards[1].alt,href:'/education?lang='+lang,cta:tr?'Eğitim seçenekleri':'Explore study options',secondary:pageHref('student'),secondaryText:tr?'Öğrenci başvurusu':'Start a student enquiry'},{kicker:tr?'YATIRIM VE İŞ DANIŞMANLIĞI':'INVESTMENT & BUSINESS ADVISORY',title:tr?'Yeni pazarlar.<br><span>Bilgiyle atılan adımlar.</span>':'New markets.<br><span>Informed decisions.</span>',text:tr?'15 ülke için resmî kaynaklı rehberler. Türkiye’de savunma sanayii, turizm ve gayrimenkul odaklı danışmanlık.':'Official-source guides for 15 countries. Dedicated coverage of Türkiye’s defence industry, tourism and real estate.',image:'/sector-manufacturing.jpg',alt:tr?'Aydınlık üretim tesisinde endüstriyel faaliyet':'Industrial activity in a bright production facility',href:'/investment?lang='+lang,cta:tr?'Yatırım seçenekleri':'Explore investment',secondary:'https://global-istihdam.mtoman.chatgpt.site/portal?type=investment&lang='+lang,secondaryText:tr?'Projenizi paylaşın':'Discuss your project'}];const sectors=[['hospitality',tr?'Turizm ve otelcilik':'Tourism & hospitality','/sector-hospitality.jpg'],['manufacturing',tr?'Üretim ve sanayi':'Manufacturing & industry','/sector-manufacturing.jpg'],['healthcare',tr?'Sağlık hizmetleri':'Healthcare','/sector-healthcare.jpg'],['education',tr?'Eğitim':'Education','/sector-education.jpg'],['care',tr?'Bakım hizmetleri':'Care services','/sector-care.jpg'],['energy',tr?'Enerji':'Energy','/energy-team.jpg']];return `<div class="pro-home"><section class="pro-home-hero"><div class="native-hero-track pro-hero-track" data-slider-title="${tr?'Global İstihdam hizmetleri':'Global İstihdam services'}">${slides.map((s,i)=>`<article class="pro-slide"><div class="pro-slide-copy"><p class="pro-eyebrow">${s.kicker}</p><${i?'h2':'h1'}>${s.title}</${i?'h2':'h1'}><p class="pro-lead">${s.text}</p><div class="pro-hero-actions"><a class="pro-button" ${s.href==='#services'?'data-scroll="services"':''} href="${s.href}">${s.cta}</a><a class="pro-hero-secondary" ${s.secondary==='#services'?'data-scroll="services"':''} href="${s.secondary}">${s.secondaryText}</a></div></div><div class="pro-slide-image"><img src="${s.image}" alt="${s.alt}" width="1800" height="1200" ${i?'loading="lazy"':'fetchpriority="high"'}></div></article>`).join('')}</div></section><div class="pro-service-strip"><div class="pro-container">${serviceCards.map(s=>`<a href="${s.href}"><span>${s.n}</span><strong>${s.tag}</strong></a>`).join('')}</div></div><section class="pro-section" id="services"><div class="pro-container"><div class="pro-section-heading"><div><p class="pro-eyebrow">${tr?'GLOBAL İSTİHDAM İLE':'WITH GLOBAL İSTİHDAM'}</p><h2>${tr?'Üç uzmanlık alanı.<br>Hedefinize odaklanan bir yaklaşım.':'Three areas of focus.<br>One approach built around you.'}</h2></div><p>${tr?'Kariyeriniz, eğitiminiz veya işiniz için. İhtiyacınızı anlayarak seçenekleri netleştiriyor ve sonraki adımları birlikte planlıyoruz.':'For your career, education or business. We help clarify your options and plan the next steps around what you need.'}</p></div><div class="pro-services">${serviceCards.map(s=>`<article class="pro-service-card"><a href="${s.href}" class="pro-service-image"><img src="${s.image}" alt="${s.alt}" width="1800" height="1200" loading="lazy"></a><div><p class="pro-eyebrow">${s.tag}</p><h3>${s.title}</h3><p>${s.text}</p><a class="pro-text-link" href="${s.href}">${s.cta}</a><a class="pro-service-secondary" href="${s.portal}">${s.portalText}</a></div></article>`).join('')}</div></div></section><section class="pro-sector-section"><div class="pro-container"><div class="pro-section-heading"><div><p class="pro-eyebrow">${tr?'SEKTÖRLERİ TANIYAN BİR YAKLAŞIM':'AN APPROACH THAT UNDERSTANDS YOUR SECTOR'}</p><h2>${tr?'İş dünyasının farklı alanlarında.':'Across the working world.'}</h2></div><a class="pro-text-link" href="/sectors?lang=${lang}">${tr?'Tüm sektörler':'All sectors'}</a></div><div class="pro-sector-rail" data-slider-title="${tr?'Çalışma alanlarımız':'Our sectors'}">${sectors.map(([slug,name,img])=>`<a class="pro-sector-card" href="/sectors/${slug}?lang=${lang}"><img src="${img}" alt="${name}" width="1800" height="1200" loading="lazy"><h3>${name}</h3><span>${tr?'Sektörü inceleyin':'Explore the sector'}</span></a>`).join('')}</div></div></section><section class="pro-section"><div class="pro-container pro-editorial"><div class="pro-editorial-image"><img src="/students-campus.jpg" alt="${serviceCards[1].alt}" width="1800" height="1200" loading="lazy"><span>${tr?'ULUSLARARASI EĞİTİM':'INTERNATIONAL EDUCATION'}</span></div><div class="pro-editorial-copy"><p class="pro-eyebrow">${tr?'ÖNE ÇIKAN EĞİTİM YOLU':'FEATURED STUDY PATHWAY'}</p><h2>${tr?'Final’de başlayın.<br>İngiltere’de devam edin.':'Start at Final.<br>Continue in England.'}</h2><p>${tr?'Uluslararası Final Üniversitesi’nin Hull Üniversitesi ile sunduğu seçili 2+2 ve 3+1 eğitim yollarını keşfedin. Program, akademik başarı ve dil koşullarını birlikte inceleyin.':'Explore selected 2+2 and 3+1 pathways between Final International University and the University of Hull, including programme, academic and language requirements.'}</p><div class="pro-pathway-line"><div><strong>2 + 2</strong><span>${tr?'İki ülkede eğitim':'Study in two countries'}</span></div><div><strong>3 + 1</strong><span>${tr?'Kıbrıs’tan İngiltere’ye':'From Cyprus to England'}</span></div></div><a class="pro-button dark" href="/universities/final-international-university?lang=${lang}">${tr?'Final Üniversitesi’ni tanıyın':'Discover Final University'}</a></div></div></section><section class="pro-investment-band"><div class="pro-container"><div><p class="pro-eyebrow">${tr?'TÜRKİYE VE ULUSLARARASI PAZARLAR':'TÜRKİYE & INTERNATIONAL MARKETS'}</p><h2>${tr?'İş fikrinizin<br>bir sonraki adresi.':'The next destination<br>for your business.'}</h2></div><div><p>${tr?'Savunma sanayii, turizm ve gayrimenkul başta olmak üzere yatırım alanlarını ve ülkelere göre kuruluş adımlarını keşfedin.':'Explore investment sectors, with a focus on defence industry, tourism and real estate, and establishment routes country by country.'}</p><div class="pro-market-list"><span>Türkiye</span><span>${tr?'Körfez':'Gulf countries'}</span><span>${tr?'Avrupa':'Europe'}</span><span>${tr?'ABD ve Kanada':'US & Canada'}</span></div><a class="pro-button" href="/investment?lang=${lang}">${tr?'Ülke rehberlerini inceleyin':'Explore the country guides'}</a></div></div></section><section class="pro-section"><div class="pro-container"><div class="pro-section-heading"><div><p class="pro-eyebrow">${tr?'AÇIK, DÜZENLİ, ERİŞİLEBİLİR':'CLEAR, ORGANISED, ACCESSIBLE'}</p><h2>${tr?'Bir sonraki adımınız<br>burada başlıyor.':'Your next step<br>starts here.'}</h2></div><a class="pro-button dark" href="https://global-istihdam.mtoman.chatgpt.site/portal?lang=${lang}">${tr?'Başvuru merkezini aç':'Open the application centre'}</a></div><ol class="pro-process">${(tr?[['Hedefinizi paylaşın','İstihdam, eğitim veya yatırım ihtiyacınıza uygun başvuru türünü seçin.'],['Bilgilerinizi tamamlayın','İletişim bilgilerinizi ve beklentilerinizi giriş yaptığınız hesabınızdan paylaşın.'],['Süreci takip edin','Başvurunuzun kaydını ve güncel değerlendirme durumunu hesabınızda görüntüleyin.']]:[['Tell us your goal','Choose the enquiry that fits your recruitment, education or investment needs.'],['Share your details','Use your signed-in account to provide your contact information and expectations.'],['Follow your progress','View your saved enquiry and its current review status in your account.']]).map(([title,text],i)=>`<li><span>0${i+1}</span><h3>${title}</h3><p>${text}</p></li>`).join('')}</ol></div></section><section class="pro-contact-band"><div class="pro-container"><div><p class="pro-eyebrow">${tr?'BİZİMLE GÖRÜŞÜN':'LET’S TALK'}</p><h2>${tr?'Hedefinizi birlikte planlayalım.':'Let’s plan what comes next.'}</h2></div><a href="tel:+905339247519">+90 (533) 924 75 19</a></div></section></div>`}
function investmentStrip(){const tr=lang==='tr';return `<section class="investment-home-band"><div class="container"><div><p class="eyebrow">${tr?'YENİ / YATIRIM VE İŞ DANIŞMANLIĞI':'NEW / INVESTMENT & BUSINESS ADVISORY'}</p><h2>${tr?'Fikrinizden yeni pazarlara.':'From your vision to new markets.'}</h2><p>${tr?'Türkiye, altı Körfez ülkesi, Avrupa, ABD ve Kanada için ülke bazında rehberler. Türkiye’de savunma sanayii, turizm ve gayrimenkul odaklı danışmanlık.':'Country guides for Türkiye, six Gulf countries, Europe, the US and Canada. A dedicated focus on Türkiye’s defence industry, tourism and real estate.'}</p></div><div class="buttons"><a class="button" href="/investment?lang=${lang}">${tr?'15 ülkeyi keşfedin':'Explore 15 countries'}</a><a class="text-link" href="https://global-istihdam.mtoman.chatgpt.site/portal?type=investment&lang=${lang}">${tr?'Danışmanlık başvurusu':'Start an advisory enquiry'}</a></div></div></section>`}
function corporatePage(){return `${pageHeader(t('navCorporate'),t('corporateIntro'))}<section class="section"><div class="container"><div class="page-grid"><article class="prose"><p class="eyebrow">${t('about')}</p><h2>${t('companyName')}</h2><p>${t('aboutText')}</p><p>${t('aboutText2')}</p><h2>${t('serviceTitle')}</h2><p>${t('serviceText')}</p></article><aside class="sidecard"><h3>${t('corporateAside')}</h3><p>${t('corporateAsideText')}</p>${route('candidate',t('navCandidate'),'button')}${route('employer',t('navEmployer'),'button secondary')}</aside></div><div class="values">${t('valueTitles').map((h,i)=>`<article class="value"><h3>${h}</h3><p>${t('valueTexts')[i]}</p></article>`).join('')}</div></div></section>${band()}`}
function field(key,type='text',required=true,full=false,options){const label=t(key);return `<div class="field${full?' full':''}"><label for="${key}">${label}${required?' <span class="required">*</span>':''}</label>${options?`<select name="${key}" id="${key}" ${required?'required':''}><option value="">${t('select')}</option>${options.map(v=>`<option>${v}</option>`).join('')}</select>`:type==='textarea'?`<textarea id="${key}" name="${key}" maxlength="3000" ${required?'required':''}></textarea>`:`<input id="${key}" name="${key}" type="${type}" ${required?'required':''} ${type==='number'?'min="1" max="10000" step="1"':'maxlength="160"'} ${key==='name'||key==='contactPerson'?'autocomplete="name"':key==='email'?'autocomplete="email"':key==='phone'?'autocomplete="tel"':key==='company'?'autocomplete="organization"':''}>`}</div>`}
function applicationPage(employer){return `${pageHeader(t(employer?'navEmployer':'navCandidate'),t(employer?'employerIntro':'candidateIntro'))}<section class="section"><div class="container">${route(employer?'employer':'candidate',t('portalCta'),'button')}</div></section>`}
function sectorsPage(){return `${pageHeader(t('sectors'),t('sectorIntro'))}<section class="section pale"><div class="container">${sectorCards(t('sectorNames').map((_,i)=>i))}</div></section>${band()}`}
function trainingPage(){return `${pageHeader(t('navTraining'),t('trainingIntro'))}<section class="section"><div class="container page-grid"><article class="prose"><h2>${t('trainingTitle')}</h2><p>${t('trainingText')}</p><div class="values">${t('trainingItems').map((x,i)=>`<article class="value"><span class="eyebrow">0${i+1}</span><h3>${x}</h3></article>`).join('')}</div></article><aside class="sidecard"><h3>${t('trainingAside')}</h3><p>${t('trainingAsideText')}</p>${route('contact',t('contactCta'),'button')}</aside></div></section>`}
function mediaPage(){return `${pageHeader(t('navMedia'),t('mediaIntro'))}<section class="section"><div class="container brand-gallery"><figure><img class="media-logo" src="/global-istihdam-logo.png" width="2172" height="724" alt="Global İstihdam Bürosu" loading="lazy"><figcaption>Global İstihdam Bürosu</figcaption></figure><figure><img src="/global-istihdam-brand-original.png" width="225" height="225" alt="Global İstihdam" loading="lazy"><figcaption>Global İstihdam</figcaption></figure></div></section>`}
function contactPage(){return `${pageHeader(t('navContact'),t('contactIntro'))}<section class="section"><div class="container page-grid"><div class="contact-info"><h2>${t('contactTitle')}</h2><div class="contact-block"><h3>${t('call')}</h3><a href="tel:+905339247519">+90 (533) 924 75 19</a></div><div class="contact-block"><h3>${t('address')}</h3><p>Mustafa Kemal Mah. 2118 Cad. No: 4/C<br>İç Kapı No: 140, Maidan İş Merkezi<br>Çankaya / Ankara, Türkiye</p></div><div class="contact-block"><h3>${t('emailLabel')}</h3><p>${t('emailUpdating')}</p></div></div><aside class="sidecard"><h3>${t('contactAside')}</h3><p>${t('contactAsideText')}</p><div class="buttons">${route('candidate',t('navCandidate'),'button')}${route('employer',t('navEmployer'),'button secondary')}</div></aside></div></section>`}
function privacyPage(){return `${pageHeader(t('privacy'),t('privacyHeading'))}<section class="section"><div class="container"><article class="prose privacy-text"><h2>${t('privacy')}</h2><p>${t('privacyCurrent')}</p><p>${t('privacyContact')}</p><a class="button" href="/privacy?lang=${lang}">${lang==='tr'?'Tam gizlilik metni':'Full privacy notice'}</a></article></div></section>`}
function closeMenu(){nav.classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');document.body.classList.remove('menu-open')}
function updateChrome(){document.querySelectorAll('[data-portal-home]').forEach(el=>el.href='https://global-istihdam.mtoman.chatgpt.site/portal?lang='+lang);document.querySelectorAll('[data-admin-home]').forEach(el=>el.href='/admin?lang='+lang);document.documentElement.lang=lang;document.querySelectorAll('[data-t]').forEach(el=>{el.textContent=t(el.dataset.t)});document.querySelectorAll('[data-page]').forEach(el=>{el.setAttribute('href',pageHref(el.dataset.page));if(el.closest('nav')){if(el.dataset.page===page)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')}});document.querySelectorAll('[data-lang]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.lang===lang)));nav.setAttribute('aria-label',lang==='tr'?'Ana menü':'Main navigation');}
function downloadDraft(event){event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const values=new FormData(form);const lines=[t('downloadHeader'),t('downloadDisclaimer'),''];for(const [key,value]of values){if(String(value).trim())lines.push(`${t(key)}: ${String(value).trim()}`)}if(draftUrl)URL.revokeObjectURL(draftUrl);draftUrl=URL.createObjectURL(new Blob(['\uFEFF'+lines.join('\n\n')],{type:'text/plain;charset=utf-8'}));const filename=`global-istihdam-${page}-${lang}.txt`;const link=document.createElement('a');link.href=draftUrl;link.download=filename;link.click();const status=document.querySelector('#form-status');status.hidden=false;status.className='form-status';status.innerHTML=`${escape(t('downloadSuccess'))}<br><a class="button secondary" style="margin-top:12px" href="${draftUrl}" download="${filename}">${t('downloadAgain')}</a>`;}
function render(){clearSliders();readRoute();closeMenu();const renderers={home:homePage,education:educationPage,corporate:corporatePage,candidate:()=>applicationPage(false),employer:()=>applicationPage(true),sectors:sectorsPage,training:trainingPage,media:mediaPage,contact:contactPage,privacy:privacyPage};main.innerHTML=renderers[page]();updateChrome();setupLandingInteractions();setupSliders();document.querySelector('#enquiry-form')?.addEventListener('submit',downloadDraft);const titles={education:'education',home:'heroLabel',corporate:'navCorporate',candidate:'navCandidate',employer:'navEmployer',sectors:'sectors',training:'navTraining',media:'navMedia',contact:'navContact',privacy:'privacy'};document.title=`${t(titles[page])} | Global İstihdam`;document.querySelector('meta[name="description"]').content=t('footerText');}
function changeLanguage(next){if(!['tr','en'].includes(next))throw new Error('Unsupported language');const previousLang=lang;const drafts=Array.from(document.querySelectorAll('[data-preference-form]'),form=>[form.dataset.preferenceForm,Array.from(new FormData(form).entries())]);const workAudience=document.querySelector('[data-work-audience][aria-pressed="true"]')?.dataset?.workAudience;const studyAudience=document.querySelector('[data-study-audience][aria-pressed="true"]')?.dataset?.studyAudience;history.replaceState(null,'',`#${next}/${page}`);try{localStorage.setItem('global-language',next)}catch{}render();for(const [type,values]of drafts){const form=document.querySelector(`[data-preference-form="${type}"]`);for(const [key,value]of values){if(key==='lang')continue;const input=form?.elements.namedItem(key);if(input)input.value=String(value)}}if(workAudience)document.querySelector(`[data-work-audience="${workAudience}"]`)?.click();if(studyAudience)document.querySelector(`[data-study-audience="${studyAudience}"]`)?.click();return {language:next,page,changed:next!==previousLang};}
document.querySelectorAll('[data-lang]').forEach(button=>button.addEventListener('click',()=>changeLanguage(button.dataset.lang)));
document.querySelector('.menu-toggle').addEventListener('click',()=>{const open=nav.classList.toggle('open');document.body.classList.toggle('menu-open',open);document.querySelector('.menu-toggle').setAttribute('aria-expanded',String(open))});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu()});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true})});
window.addEventListener('beforeunload',()=>{if(draftUrl)URL.revokeObjectURL(draftUrl)});

Object.assign(content.tr,{education:'Üniversiteler & Öğrenciler',portalCta:'Başvuru Portalına Girin',privacyHeading:'Başvurular ve kişisel bilgileriniz',privacyCurrent:'Çalışan, işveren, öğrenci, üniversite ve yatırım başvuruları güvenli giriş gerektiren başvuru merkezinde kaydedilir. İletişim bilgileri, tercihler ve isteğe bağlı özgeçmiş, başvurunuzu değerlendirmek ve sizinle iletişim kurmak amacıyla saklanır. Kendi başvurularınızı siz ve yetkili yönetici görebilir. Başka işverenlere veya üniversitelere otomatik aktarım yapılmaz.',privacyContact:'Düzeltme veya silme talepleri için +90 (533) 924 75 19 numarasından iletişime geçebilirsiniz. Dil tercihiniz tarayıcıda saklanır. Bu portal önizlemesinde yalnızca deneme verileri kullanın; kamusal başvurular açılmadan önce şirketin ayrıntılı aydınlatma metni ve saklama politikası tamamlanacaktır.',eduEyebrow:'ULUSLARARASI EĞİTİM',eduTitle:'Eğitiminiz için<br>yeni bir ufuk.',eduIntro:'Pakistan, Orta Asya ve Afrika’dan öğrenciler için Azerbaycan, Kuzey Kıbrıs, Almanya, Avrupa, Kanada ve ABD odaklı üniversite başvuru danışmanlığı.',studentCta:'Öğrenci Başvurusu',universityCta:'Üniversite İş Birliği',destTitle:'Eğitim Bölgelerimiz',destIntro:'Hedefinizi seçin. Eğitim seviyenizi ve ilgi alanınızı paylaşın.',destinations:['Azerbaycan','Kuzey Kıbrıs','Almanya','Avrupa · Diğer Ülkeler','Kanada','ABD'],destText:['Azerbaycan’daki üniversite seçeneklerine yönelik başvuru danışmanlığı talebi.','Kuzey Kıbrıs’taki üniversitelerin programları ve başvuru süreçlerine yönelik danışmanlık talebi.','Avrupa ülkelerindeki üniversiteler için bölüm, eğitim dili ve öğrenim hedefi odaklı danışmanlık talebi.','Kanada ve Amerika Birleşik Devletleri’ndeki üniversiteler için eğitim planlama ve başvuru danışmanlığı talebi.'],focusTitle:'Yerel hedefler. Uluslararası eğitim.',focusText:'Öğrenci iletişimimizin odağında Pakistan, Orta Asya ve Afrika yer alıyor. Her öğrencinin eğitim hedefini ve program tercihlerini ayrı değerlendiriyoruz.',regions:['Pakistan','Orta Asya','Afrika'],studentTitle:'Öğrenciler İçin',studentText:'Eğitim bölgenizi, bölümünüzü ve hedeflediğiniz seviyeyi paylaşın. Başvurunuzu kaydedin ve durumunu hesabınızdan takip edin.',universityTitle:'Üniversiteler İçin',universityText:'Kurumunuzu, programlarınızı ve öğrenci temini beklentilerinizi tanıtın. İş birliği talepleri ayrı olarak değerlendirilir.',eduSteps:['Hedeflerinizi paylaşın','Tercihlerinizi değerlendirelim','Başvuru sürecini planlayalım'],eduNote:'Bu hizmet ilk değerlendirme ve danışmanlık içindir. Üniversite kabulü, burs veya vize garantisi verilmez. Üniversite ortaklıkları henüz ilan edilmemiştir.'});
Object.assign(content.en,{education:'Universities & Students',portalCta:'Open Application Portal',privacyHeading:'Applications and your personal information',privacyCurrent:'Employee, employer, student, university and investment enquiries are stored in the application centre after sign-in. Contact details, preferences and an optional CV are saved to assess your application and contact you. You and the authorised administrator can view your records. Information is not automatically sent to employers or universities.',privacyContact:'For correction or deletion requests, call +90 (533) 924 75 19. Your language preference is stored in your browser. Use test data only in this portal preview; the company’s detailed privacy notice and retention policy must be completed before public applications open.',eduEyebrow:'INTERNATIONAL EDUCATION',eduTitle:'A new horizon<br>for your education.',eduIntro:'University application consultancy for students from Pakistan, Central Asia and Africa, focused on Azerbaijan, North Cyprus, Germany, Europe, Canada and the USA.',studentCta:'Student Application',universityCta:'University Cooperation',destTitle:'Study Destinations',destIntro:'Choose your destination. Share your study level and subject interests.',destinations:['Azerbaijan','North Cyprus','Germany','Europe · Other Countries','Canada','USA'],destText:['Request application consultancy for university options in Azerbaijan.','Request guidance on university programmes and application processes in North Cyprus.','Discuss universities across Europe based on your subject, language of study and academic goals.','Request education planning and application consultancy for universities in Canada and the United States.'],focusTitle:'Local aspirations. International education.',focusText:'Our student outreach focuses on Pakistan, Central Asia and Africa. We consider each student’s academic goals and programme preferences individually.',regions:['Pakistan','Central Asia','Africa'],studentTitle:'For Students',studentText:'Share your preferred destination, subject and study level. Save your enquiry and follow its progress in your account.',universityTitle:'For Universities',universityText:'Introduce your institution, programmes and student recruitment needs. Cooperation enquiries are reviewed separately.',eduSteps:['Share your goals','Explore your preferences','Plan your application'],eduNote:'This service provides preliminary assessment and consultancy. Admission, scholarships and visas are not guaranteed. University partnerships have not yet been announced.'});
const studyDestinationValues=['Azerbaijan','North Cyprus','Germany','Europe','Canada','USA'];
const studyLevelValues=['Undergraduate','Master’s','Doctoral','Language / Foundation'];
function studyLink(index){return `https://global-istihdam.mtoman.chatgpt.site/portal?type=student&lang=${lang}&destination=${encodeURIComponent(studyDestinationValues[index])}`}
function educationStrip(){return `<section class="education-promo"><div class="container education-promo-grid"><div><p class="eyebrow">${t('eduEyebrow')}</p><h2>${t('eduTitle')}</h2><p>${t('eduIntro')}</p>${route('education',t('education'),'button')}</div><img src="/students-campus.jpg" width="1800" height="1200" alt="${t('studentPhoto')}" loading="lazy"></div></section>`}
function educationPage(){return `<div class="education-site"><div class="education-subnav"><div class="container"><span>${t('eduEyebrow')}</span><button data-scroll="study-planner">${t('studentCta')}</button><button data-scroll="study-destinations">${t('destTitle')}</button><button data-scroll="study-journey">${t('studyHow')}</button>${route('university',t('universityCta'))}</div></div><section class="study-hero"><div class="container">${featureSlides(true)}</div></section><section class="container study-planner" id="study-planner" tabindex="-1"><div class="study-planner-tabs" aria-label="${t('studyAudience')}"><button type="button" data-study-audience="student" aria-pressed="true">${t('studentTitle')}</button><button type="button" data-study-audience="university" aria-pressed="false">${t('universityTitle')}</button></div><div id="study-student-panel"><h2>${t('studyPlanTitle')}</h2><form class="study-planner-form" data-preference-form="student" method="get" action="https://global-istihdam.mtoman.chatgpt.site/portal"><input type="hidden" name="type" value="student"><input type="hidden" name="lang" value="${lang}"><label>${t('studySubject')}<input name="field" maxlength="180" placeholder="${t('studySubjectHint')}" required></label><label>${t('studyLevel')}<select name="level" required><option value="">${t('select')}</option>${t('studyLevels').map((x,i)=>`<option value="${escape(studyLevelValues[i])}">${x}</option>`).join('')}</select></label><label>${t('studyDestination')}<select name="destination" required><option value="">${t('select')}</option>${t('destinations').map((x,i)=>`<option value="${studyDestinationValues[i]}">${x}</option>`).join('')}</select></label><button class="button" type="submit">${t('studyContinue')}</button></form><p class="study-planner-note">${t('studyPlanNote')}</p></div><div id="study-university-panel" hidden><h2>${t('universityTitle')}</h2><p>${t('universityText')}</p>${route('university',t('universityCta'),'button')}</div></section><section class="section study-destinations" id="study-destinations"><div class="container"><div class="section-head"><div><p class="eyebrow">${t('studyDiscover')}</p><h2>${t('destTitle')}</h2></div><p>${t('destIntro')}</p></div><div class="study-destination-grid">${t('destinations').map((x,i)=>`<article class="study-destination-card"><div class="destination-heading"><span class="destination-code" aria-hidden="true">${['AZ','KKTC','DE','EU','CA','US'][i]}</span><span class="destination-region">${t('destRegions')[i]}</span></div><h3>${x}</h3><p>${t('destText')[i]}</p><a href="/education/${['azerbaijan','north-cyprus','germany','europe','canada','usa'][i]}?lang=${lang}" class="text-link">${lang==='tr'?'Üniversiteleri keşfet':'Explore universities'}</a></article>`).join('')}</div></div></section><section class="final-feature"><div class="container"><div><p class="eyebrow">${lang==='tr'?'KUZEY KIBRIS’TAN İNGİLTERE’YE':'FROM NORTH CYPRUS TO ENGLAND'}</p><h2>${lang==='tr'?'Final’de başlayın.<br>İngiltere’de devam edin.':'Start at Final.<br>Continue in England.'}</h2><p>${lang==='tr'?'Uluslararası Final Üniversitesi’nin Hull Üniversitesi ile sunduğu 2+2 ve 3+1 eğitim yollarını keşfedin.':'Explore Final International University’s 2+2 and 3+1 study pathways with the University of Hull.'}</p><a class="button" href="/universities/final-international-university?lang=${lang}">${lang==='tr'?'Final Üniversitesi’ni tanıyın':'Discover Final University'}</a></div><div class="pathway-numbers"><strong>3 <span>+</span> 1</strong><p>${lang==='tr'?'3 yıl Kuzey Kıbrıs · 1 yıl İngiltere':'3 years North Cyprus · 1 year England'}</p><a href="/education/north-cyprus?lang=${lang}">${lang==='tr'?'Kuzey Kıbrıs’taki tüm üniversiteler':'All universities in North Cyprus'}</a></div></div></section><section class="section study-journey" id="study-journey"><div class="container"><div class="section-head"><h2>${t('studyJourneyTitle')}</h2><p>${t('studyJourneyIntro')}</p></div><ol class="study-steps">${t('studyStepTitles').map((x,i)=>`<li><span class="study-step-number">0${i+1}</span><h3>${x}</h3><p>${t('studyStepTexts')[i]}</p></li>`).join('')}</ol></div></section><section class="section"><div class="container study-partnership"><div><p class="eyebrow">${t('universityTitle')}</p><h2>${t('studyPartnerTitle')}</h2><p>${t('universityText')}</p><div class="region-chips">${t('regions').map(x=>`<span>${x}</span>`).join('')}</div>${route('university',t('universityCta'),'button')}</div><aside><p class="eyebrow">${t('studyTalk')}</p><h3>${t('studyQuestion')}</h3><p>${t('studyHelpText')}</p><a href="tel:+905339247519">+90 (533) 924 75 19</a></aside></div></section><div class="container"><p class="education-note">${t('eduNote')}</p></div></div>`}
function setupLandingInteractions(){document.querySelectorAll('[data-scroll]').forEach(button=>button.addEventListener('click',event=>{event.preventDefault();const target=document.getElementById(button.dataset.scroll);target?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});if(target?.hasAttribute('tabindex'))target.focus({preventScroll:true})}));document.querySelectorAll('[data-study-audience]').forEach(button=>button.addEventListener('click',()=>{const value=button.dataset.studyAudience;document.querySelectorAll('[data-study-audience]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.studyAudience===value)));document.getElementById('study-student-panel').hidden=value!=='student';document.getElementById('study-university-panel').hidden=value!=='university'}));document.querySelectorAll('[data-work-audience]').forEach(button=>button.addEventListener('click',()=>{const value=button.dataset.workAudience;document.querySelectorAll('[data-work-audience]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.workAudience===value)));document.getElementById('work-candidate').hidden=value!=='candidate';document.getElementById('work-employer').hidden=value!=='employer'}));}

